examples.setup:
var period by rememberSaveable { mutableStateOf("Last 7 days") }
val periods = listOf("Today", "Last 7 days", "Last 30 days", "This quarter", "Custom")
var editing by remember { mutableStateOf(false) }
var layout by remember { mutableStateOf(emptyList<String>()) }
var done by rememberSaveable { mutableStateOf(setOf("t3")) }
val tiles = listOf("Today", "Assigned to you", "Due soon", "Progress", "Announcements", "Your team", "Recent activity")
val now = 1_781_517_600_000L
val tasks = listOf(
    "t1" to "Reply to the Harbor Labs request",
    "t2" to "Review the checkout redesign",
    "t3" to "Send the sprint notes",
)
val row: @Composable (String, String) -> Unit = { label, value ->
    Row(verticalAlignment = Alignment.CenterVertically) {
        MonarchText(text = label, modifier = Modifier.weight(1f))
        MonarchText(text = value)
    }
}
val events = listOf(
    MonarchActivityTimelineEvent(
        id = "e1",
        verb = "commented on",
        time = 1_781_516_400_000L,
        actor = MonarchActivityTimelineActor("Jonas Weber"),
        target = "Checkout redesign",
    ),
    MonarchActivityTimelineEvent(
        id = "e2",
        verb = "assigned you",
        time = 1_781_510_700_000L,
        actor = MonarchActivityTimelineActor("Amara Okafor"),
        target = "Update the pricing page",
    ),
)
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag("en-GB")) }
}

