            val groups = if (text.isEmpty()) {
                // Recent places while nothing is typed, then every channel and person, as on the web.
                listOf(MonarchSearchResultGroup("Recent", "recent", recent.map { MonarchSearchResult(it.second, it.first, snippet = snippets[it.first], icon = { MonarchIcon(if (it.third == "People") SampleIcons.Users else SampleIcons.Inbox, contentDescription = null) }) })) +
                    destinations.groupBy { it.third }
                        .map { (group, list) ->
                            MonarchSearchResultGroup(group, group, list.map { MonarchSearchResult(it.second, it.first, snippet = snippets[it.first], icon = { MonarchIcon(if (it.third == "People") SampleIcons.Users else SampleIcons.Inbox, contentDescription = null) }) })
                        }
            } else {
                destinations.filter { it.second.contains(text, ignoreCase = true) }
                    .groupBy { it.third }
                    .map { (group, list) ->
                        MonarchSearchResultGroup(group, group, list.map { MonarchSearchResult(it.second, it.first, snippet = snippets[it.first], icon = { MonarchIcon(if (it.third == "People") SampleIcons.Users else SampleIcons.Inbox, contentDescription = null) }) })
                    } +
                    // The search-everywhere fallback under the instant matches.
                    MonarchSearchResultGroup("Search", "search", listOf(MonarchSearchResult("Search for “$text”", "search")))
            }
            MonarchSearchResults(
                groups = groups,
                onSelect = { result, _ ->
                    opened = result.title
                    open = false
                    query = ""
                },
                modifier = Modifier.heightIn(max = 520.dp),
                query = query,
            )
        }
    }
}

