    MonarchAssigneePerson("m1", "Alex Morgan", email = "alex@example.com"),
    MonarchAssigneePerson("m2", "Priya Shah", email = "priya@example.com"),
    MonarchAssigneePerson("m3", "Jordan Lee", email = "jordan@example.com"),
)
val snackbars = remember { SnackbarHostState() }
val scope = rememberCoroutineScope()
var open by remember { mutableStateOf(true) }
var step by remember { mutableIntStateOf(0) }
var allTo by remember { mutableStateOf<String?>(null) }
var perItem by remember { mutableStateOf(false) }
val each = remember { mutableStateMapOf<String, String?>() }
var removing by remember { mutableStateOf(false) }
var failure by remember { mutableStateOf<String?>(null) }
fun assigneeOf(workId: String): String? = if (perItem) each[workId] else allTo

examples.code:
Scaffold(snackbarHost = { MonarchSnackbarHost(hostState = snackbars) }) { padding ->
    MonarchButton(
        text = "Remove Jordan Lee",
        onClick = {
            step = 0
            allTo = null
            perItem = false
            each.clear()
            open = true
        },
        modifier = Modifier.padding(padding),
        variant = MonarchButtonVariant.Danger,
    )
}
if (open) {
    MonarchBottomSheet(onDismissRequest = { open = false }, title = "Remove Jordan Lee", dismissible = !removing) {
        val sheet = this
        Column(
            modifier = Modifier.verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
        ) {
            MonarchText(text = "Step ${step + 1} of 2", style = MonarchTextStyle.Caption)
            MonarchProgress(progress = (step + 1) / 2f, size = MonarchProgressSize.Sm)
            if (step == 0) {
                MonarchText(text = "Hand over their open work", style = MonarchTextStyle.Heading)
                MonarchText(text = "Choose who takes over what Jordan Lee still owns, or leave it unassigned.")
                if (!perItem) {
                    MonarchAssigneePicker(
                        people = people,
                        selected = allTo,
                        onSelectedChange = { allTo = it },
                        currentUserId = "me",
                        showAssignToMe = false,
                        labels = MonarchAssigneePickerLabels(label = "Reassign all open work to", unassigned = "Leave unassigned"),
                    )
                }
                MonarchCheckboxRow(
                    checked = perItem,
                    onCheckedChange = { on ->
                        if (on) work.forEach { each[it.id] = allTo }
                        perItem = on
                    },
                    label = "Choose a person for each kind of work",
                )
                if (perItem) {
                    work.forEach { w ->
                        MonarchAssigneePicker(
                            people = people,
                            selected = each[w.id],
                            onSelectedChange = { each[w.id] = it },
                            showAssignToMe = false,
                            labels = MonarchAssigneePickerLabels(label = "${w.count} ${w.label}", unassigned = "Leave unassigned"),
                        )
                    }
                }
                MonarchButton(
                    text = "Cancel",
                    onClick = { open = false },
                    modifier = Modifier.fillMaxWidth(),
                    variant = MonarchButtonVariant.Ghost,
                )
                MonarchButton(
                    text = "Continue",
                    onClick = { step = 1 },
                    modifier = Modifier.fillMaxWidth(),
                    variant = MonarchButtonVariant.Primary,
                )
            } else {
                MonarchText(text = "Confirm removal", style = MonarchTextStyle.Heading)
                MonarchMemberRow(name = "Jordan Lee", email = "jordan@example.com")
                MonarchConsequenceList(
                    items = listOf(MonarchConsequence(MonarchConsequenceKind.Removed, "Jordan Lee loses access to the workspace")) +
                        work.map { w ->
                            val to = people.firstOrNull { it.id == assigneeOf(w.id) }?.name
                            if (to != null) {
                                MonarchConsequence(MonarchConsequenceKind.Changed, "${w.count} ${w.label} go to $to")
                            } else {
                                MonarchConsequence(MonarchConsequenceKind.Warning, "${w.count} ${w.label} are left unassigned")
                            }
                        } +
                        MonarchConsequence(MonarchConsequenceKind.Kept, "Their past activity and comments stay"),
                )
                failure?.let { MonarchInlineNotice(message = it, tone = MonarchTone.Danger) }
                MonarchButton(
                    text = "Remove member",
                    onClick = {
                        removing = true
                        failure = null
                        scope.launch {
                            // Send the removal and work.map { it.id to assigneeOf(it.id) } to the server here.
                            // On failure: failure = "Couldn’t remove Jordan Lee. Try again."; removing = false
                            removing = false
                            sheet.dismiss()
                            val result = snackbars.showSnackbar(
                                message = "Jordan Lee removed",
                                actionLabel = "Undo",
                                duration = SnackbarDuration.Long,
                            )
                            if (result == SnackbarResult.ActionPerformed) {
                                // Restore the membership and the work on the server.
                            }
                        }
                    },
                    modifier = Modifier.fillMaxWidth(),
                    variant = MonarchButtonVariant.Danger,
                    loading = removing,
                )
                MonarchButton(
                    text = "Back",
                    onClick = { step = 0 },
                    modifier = Modifier.fillMaxWidth(),
                    variant = MonarchButtonVariant.Ghost,
                    enabled = !removing,
                )
            }
        }
    }
}

